BEGIN;
CREATE TABLE IF NOT EXISTS oca.branch_scan_runs(run_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),scope_id UUID NOT NULL REFERENCES knowledge.scopes(scope_id),started_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ,status TEXT NOT NULL CHECK(status IN ('running','succeeded','partial','failed')),repositories_attempted INTEGER NOT NULL DEFAULT 0,repositories_succeeded INTEGER NOT NULL DEFAULT 0,repositories_failed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS oca.repository_ref_snapshots(snapshot_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),run_id UUID NOT NULL REFERENCES oca.branch_scan_runs(run_id),repository_id BIGINT NOT NULL REFERENCES oca.repositories(repository_id),artifact_id UUID NOT NULL REFERENCES source_registry.artifacts(artifact_id),content_sha256 TEXT NOT NULL CHECK(content_sha256 ~ '^[0-9a-f]{64}$'),scanned_at TIMESTAMPTZ NOT NULL,UNIQUE(run_id,repository_id));
CREATE TABLE IF NOT EXISTS oca.repository_branches(repository_id BIGINT NOT NULL REFERENCES oca.repositories(repository_id),branch_name TEXT NOT NULL,commit_sha TEXT NOT NULL CHECK(commit_sha ~ '^[0-9a-f]{40}$'),last_scan_run_id UUID NOT NULL REFERENCES oca.branch_scan_runs(run_id),last_verified_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(repository_id,branch_name));
CREATE TABLE IF NOT EXISTS oca.branch_scan_issues(run_id UUID NOT NULL REFERENCES oca.branch_scan_runs(run_id),repository_id BIGINT NOT NULL REFERENCES oca.repositories(repository_id),error_code TEXT NOT NULL,message TEXT NOT NULL,PRIMARY KEY(run_id,repository_id));
INSERT INTO platform.schema_migrations(migration_id,checksum) VALUES('014_oca_branch_inventory','managed-by-repository') ON CONFLICT DO NOTHING;
COMMIT;
